#!/usr/bin/env python3
"""The plugin's one action: can the bridge see the floor, and what will it prompt.

Read only. Runs the same code paths the MCP server runs, so a green check here
means the server would work, not that a similar-looking command worked.

Exit codes: 0 all green, 1 the socket is not reachable, 2 the allow list is
empty (the bridge would refuse every prompt target).
"""

from __future__ import annotations

import json
import os
import subprocess
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))

import hq_floor_mcp as bridge  # noqa: E402

SERVER = Path(__file__).resolve().parent / "hq_floor_mcp.py"


def main() -> int:
    rc = 0
    print(f"server      {SERVER}")
    print(f"herdr       {bridge.HERDR}")
    print(f"corridor    {bridge.FLOOR_DIR / 'inbox'}")

    patterns = bridge.prompt_allow_patterns()
    source = (
        "HQ_FLOOR_PROMPT_ALLOW"
        if "HQ_FLOOR_PROMPT_ALLOW" in os.environ
        else "built in default"
    )
    print(f"allow list  {', '.join(patterns) or '(empty)'}   [{source}]")
    if not patterns:
        print("            WARNING: empty, floor_prompt would refuse every target")
        rc = 2

    try:
        out = bridge._herdr("workspace", "list")
        n = len(out["result"].get("workspaces", []))
        print(f"socket      reachable, {n} workspace(s)")
    except (bridge.ToolError, OSError, subprocess.SubprocessError, KeyError) as exc:
        print(f"socket      UNREACHABLE: {exc}")
        rc = rc or 1

    snippet = {
        "mcpServers": {"hq-floor": {"command": "python3", "args": [str(SERVER)]}}
    }
    print("\nclaude_desktop_config.json:")
    print(json.dumps(snippet, indent=2))
    return rc


if __name__ == "__main__":
    sys.exit(main())
